#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    // Bit i means subset sum i + low is reachable; |sum| <= 200000 so 200001 bits suffice.
    static bitset<200001> bits;
    bits[0] = 1;
    long long low = 0, total = 0;
    for (long long v : a) {
        total += v;
        // Positive v: shift the "take" branch up. Negative v: shift the "skip" branch up and lower the base.
        bits |= bits << (size_t)llabs(v);
        if (v < 0) low += v;
    }
    long long half = total >= 0 ? total / 2 : -((-total + 1) / 2); // floor(total / 2)
    long long limit = half - low, chosen = low;
    for (long long i = min<long long>(limit, 200000); i >= 0; i--)
        if (bits[i]) { chosen = i + low; break; }
    printf("%lld\n", llabs(total - 2 * chosen));
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] a = new long[n];
        int span = 0;
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; span += Math.abs(a[i]); }
        // Bit i means subset sum i + low is reachable.
        int words = span / 64 + 1;
        long[] bits = new long[words];
        bits[0] = 1;
        long low = 0, total = 0;
        for (long v : a) {
            total += v;
            // Positive v: shift the "take" branch up. Negative v: shift the "skip" branch up and lower the base.
            int s = (int) Math.abs(v), q = s >>> 6, r = s & 63;
            if (s > 0) {
                for (int i = words - 1; i >= q; i--) {
                    long shifted = bits[i - q] << r;
                    if (r != 0 && i - q - 1 >= 0) shifted |= bits[i - q - 1] >>> (64 - r);
                    bits[i] |= shifted;
                }
            }
            if (v < 0) low += v;
        }
        long limit = Math.floorDiv(total, 2) - low, chosen = low;
        for (long i = Math.min(limit, (long) words * 64 - 1); i >= 0; i--)
            if ((bits[(int) (i >>> 6)] >>> (i & 63) & 1) != 0) { chosen = i + low; break; }
        System.out.println(Math.abs(total - 2 * chosen));
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	a := make([]int, n)
	span := 0
	for i := range a {
		a[i] = nextInt()
		span += abs(a[i])
	}
	// Bit i means subset sum i + low is reachable.
	words := span/64 + 1
	bits := make([]uint64, words)
	bits[0] = 1
	low, total := 0, 0
	for _, v := range a {
		total += v
		// Positive v: shift the "take" branch up. Negative v: shift the "skip" branch up and lower the base.
		s := abs(v)
		q, r := s/64, uint(s%64)
		if s > 0 {
			for i := words - 1; i >= q; i-- {
				shifted := bits[i-q] << r
				if r != 0 && i-q-1 >= 0 {
					shifted |= bits[i-q-1] >> (64 - r)
				}
				bits[i] |= shifted
			}
		}
		if v < 0 {
			low += v
		}
	}
	half := total / 2
	if total < 0 && total%2 != 0 {
		half-- // floor division
	}
	limit, chosen := half-low, low
	for i := min(limit, words*64-1); i >= 0; i-- {
		if bits[i/64]>>(uint(i)%64)&1 != 0 {
			chosen = i + low
			break
		}
	}
	fmt.Println(abs(total - 2*chosen))
}
